	512: ["Path of the Magus Staff", "Fires two staff shots and one meteor. The staff shots deal 20-40 armor piercing damage. The Meteor shot deals 300-400 damage at a 33% fire rate."],
	513: ["Path of the Sniper Staff", "Fires two long range accelerating shots that deal 100-165 damage at a 70% rate of fire."],
	514: ["Path of the Stalwart Staff", "Fires one shorter range shot that deals 170-215 damage."],
	515: ["Path of the Swiftblade Staff", "Fires three shots, the outer two deal 50-75 damage. The inner shot deals 70-75 damage."],
	516: ["Path of the Magus Sword", "Fires two shots that deal 130-160 damage."],
	517: ["Path of the Sniper Sword", "Fires one long range accelerating shot that deals 350-400 damage at a 70% rate of fire."],
	518: ["Path of the Stalwart Sword", "Fires two shots that deal 140-190 damage at a 90% rate of fire. These shots decelerate and linger briefly."],
	519: ["Path of the Swiftblade Sword", "Fires one shot that deals 160-170 damage at a 175% rate of fire."],
	520: ["Path of the Magus Dagger", "Fires two shots the center shot deals 100-135 damage. The outer shot deals 100-175 damage. Both shots have a 75% rate of fire."],
	521: ["Path of the Sniper Dagger", "Fires one long range accelerating shot that deals 180-260 damage at an 80% fire rate."],
	522: ["Path of the Stalwart Dagger", "Fires three shots that deal 110-150 damage at a 50% fire rate. These shots decelerate and linger briefly"],
