	525: ["Path of the Sniper Wand", "Fires one long range accelerating shot that deals 175-215 damage at an 80% rate of fire."],
	526: ["Path of the Stalwart Wand", "Fires three shots that deal 60-110 damage at a 70% fire rate. These shots decelerate and linger briefly."],
	527: ["Path of the Swiftblade Wand", "Fires one shot that deals 90-115 damage at 175% rate of fire."],
	528: ["Path of the Magus Bow", "Fires two outer and one inner shot. The outer shots converge at the middle and end of the weapons range and deal 30-40 armor piercing damage. The inner shot deals 120-150 damage."],
	529: ["Path of the Sniper Bow", "Fires two outer and one inner shots that accelerate and have a tight spread. The outer shots deal 40-60 damage at an 80% rate of fire. The inner shot does 200-420 damage at a 40% rate of fire."],
	530: ["Path of the Stalwart Bow", "Fires four outer and one inner shot. The outer shots do 20-30 armor piercing damage but do not pierce enemies. The inner shot deals 100-190 damage."],
	531: ["Path of the Swiftblade Bow", "Fires two outer and one inner shot. The outer shots deal 20-30 armor piercing damage. The inner shot deals 80-110 damage. All shots are fired at a rate of 150%."],
	532: ["Path of the Magus Katana", "Fires three shots, two of which have a wide amplitude and deal 85-135 damage. One shot fires straight and deals 70-110 armor piercing damage at a 50% rate of fire."],
