	534: ["Path of the Stalwart Katana", "Fires two shots dealing 130-165 damage at 70% fire rate. These shots decelerate to a stop and linger briefly."],
	535: ["Path of the Swiftblade Katana", "Fires two parallel shots that deal 80-100 damage at 115% fire rate."],
